begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
select ok(not has_function_privilege('anon','public.classroom_lifecycle(uuid,uuid,text)','execute'),'anonymous start denied');
select ok(not has_function_privilege('authenticated','public.append_classroom_internal(uuid,uuid,text,jsonb,text,jsonb)','execute'),'internal append denied');
select ok(not has_function_privilege('authenticated','public.abandon_classroom_internal(uuid)','execute'),'internal abandon denied');
select ok(not has_function_privilege('authenticated','public.require_classroom_preview(uuid)','execute'),'authorization helper internal');
insert into auth.users(id,email_confirmed_at) values('a6000000-0000-0000-0000-000000000001',now()),('a6000000-0000-0000-0000-000000000002',now()),('a6000000-0000-0000-0000-000000000003',now()),('a6000000-0000-0000-0000-000000000004',now()),('a6000000-0000-0000-0000-000000000005',null);
insert into public.users(id,role) values('a6000000-0000-0000-0000-000000000001','PARENT'),('a6000000-0000-0000-0000-000000000002','PARENT'),('a6000000-0000-0000-0000-000000000003','STUDENT'),('a6000000-0000-0000-0000-000000000004','ADMIN'),('a6000000-0000-0000-0000-000000000005','PARENT');
insert into public.parent_profiles(user_id,display_name) values('a6000000-0000-0000-0000-000000000001','A'),('a6000000-0000-0000-0000-000000000002','B'),('a6000000-0000-0000-0000-000000000005','Unverified');
insert into public.student_profiles(id,user_id,display_name,grade) values('a6100000-0000-0000-0000-000000000001','a6000000-0000-0000-0000-000000000003','Selected',8),('a6100000-0000-0000-0000-000000000002',null,'Other',8),('a6100000-0000-0000-0000-000000000003',null,'Sibling',8);
insert into public.parent_student_relationships values('a6000000-0000-0000-0000-000000000001','a6100000-0000-0000-0000-000000000001'),('a6000000-0000-0000-0000-000000000002','a6100000-0000-0000-0000-000000000002'),('a6000000-0000-0000-0000-000000000001','a6100000-0000-0000-0000-000000000003');
insert into auth.sessions(id,user_id) values('a6200000-0000-0000-0000-000000000001','a6000000-0000-0000-0000-000000000001'),('a6200000-0000-0000-0000-000000000002','a6000000-0000-0000-0000-000000000001');
select set_config('request.jwt.claims','{"sub":"a6000000-0000-0000-0000-000000000001","session_id":"a6200000-0000-0000-0000-000000000001"}',true);
set local role authenticated;
select public.enroll_parent_student(gen_random_uuid(),'a6100000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000101',jsonb_build_object('schemaVersion',1,'timezone','UTC','lessonDurationMinutes',30,'weeklyFrequency',1,'slots',jsonb_build_array(jsonb_build_object('weekday',1,'time','16:00')),'earliestDate',(current_date+7)::text));
reset role;
create temp table fixture as select id,lesson_position from public.lesson_schedules where student_id='a6100000-0000-0000-0000-000000000001';
grant select on fixture to authenticated;
select ok(not has_function_privilege('anon','public.maya_mock_operation(uuid,uuid,integer,text,uuid)','execute'),'anonymous Maya denied');
select ok(not has_function_privilege('authenticated','public.maya_mock_plan_internal(uuid)','execute'),'internal planner denied');
select ok(not has_function_privilege('authenticated','public.maya_mock_templates_internal()','execute'),'internal script denied');
select ok(not has_function_privilege('authenticated','public.maya_mock_event_schema_internal()','execute'),'internal validator denied');
set local role authenticated;
select throws_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),0,'start')$$,'42501',null,'parent mode cannot activate mock teaching');
select public.begin_student_preview('a6100000-0000-0000-0000-000000000001');
select throws_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),0,'start')$$,'42501',null,'classroom must be active');
select public.classroom_lifecycle((select id from fixture where lesson_position=1),gen_random_uuid(),'start');
select throws_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),0,'openai')$$,'22023',null,'provider cannot be supplied by browser');
select lives_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),'a6300000-0000-4000-8000-000000000001',0,'start')$$,'start authorized simulation');
select lives_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),'a6300000-0000-4000-8000-000000000001',0,'start')$$,'exact initialization retry');
select is((select count(*)::integer from public.lesson_plans),1,'one canonical teaching plan');
select is((select plan->'provenance'->>'provider' from public.lesson_plans),'mock','plan marked mock');
select is((select plan->'provenance'->>'publicationReference' from public.lesson_plans),'00000000-0000-0000-0000-000000000101','exact pinned publication');
select is((select plan->'newSkills'->>0 from public.lesson_plans),'00000000-0000-0000-0000-000000000011','only planned integer skill');
select ok((select plan->'homeworkIntent'='null'::jsonb from public.lesson_plans),'no homework assignment proposal');
select throws_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),'a6300000-0000-4000-8000-000000000001',0,'advance')$$,'22023',null,'request cannot change meaning');
select throws_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),0,'start')$$,'22023',null,'new request cannot restart simulation');
select lives_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),'a6300000-0000-4000-8000-000000000002',0,'advance')$$,'first narration and board instruction issued');
select is((public.classroom_replay((select id from fixture where lesson_position=1),0)->'events'->3->>'kind'),'maya_explanation_started','ordered explanation after initialization');
select is((public.classroom_replay((select id from fixture where lesson_position=1),0)->'events'->4->>'kind'),'maya_whiteboard_issued','board issued after narration');
select throws_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),0,'advance')$$,'40001',null,'cannot skip pending explanation');
select throws_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),0,'apply','a6300000-0000-4000-8000-000000000002')$$,'40001',null,'early board acknowledgement rejected');
reset role;
update public.lessons set maya_pending_at=clock_timestamp()-interval '2 seconds';
set local role authenticated;
select lives_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),'a6300000-0000-4000-8000-000000000003',0,'apply','a6300000-0000-4000-8000-000000000002')$$,'board applied at simulated playback offset');
select lives_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),'a6300000-0000-4000-8000-000000000003',0,'apply','a6300000-0000-4000-8000-000000000002')$$,'duplicate apply idempotent');
select throws_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),0,'apply','a6300000-0000-4000-8000-000000000002')$$,'22023',null,'second ID cannot duplicate board application');
select throws_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),0,'complete','a6300000-0000-4000-8000-000000000002')$$,'40001',null,'early narration completion rejected');
select lives_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),0,'interrupt','a6300000-0000-4000-8000-000000000002')$$,'interruption increments epoch');
select is((select interruption_epoch from public.lessons),1,'canonical epoch advanced');
select throws_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),0,'complete','a6300000-0000-4000-8000-000000000002')$$,'40001',null,'delayed superseded completion rejected');
select lives_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),'a6300000-0000-4000-8000-000000000004',1,'advance')$$,'resume interrupted step from actual board');
select is((select maya_step from public.lessons),0,'interruption retries same academic step');
select throws_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),1,'apply','a6300000-0000-4000-8000-000000000002')$$,'40001',null,'old speech cannot apply in new generation');
reset role;
update public.lessons set maya_pending_at=clock_timestamp()-interval '5 seconds';
set local role authenticated;
select throws_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),1,'apply','a6300000-0000-4000-8000-000000000004')$$,'22023',null,'already committed board action is not duplicated after interruption');
select lives_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),1,'complete','a6300000-0000-4000-8000-000000000004')$$,'narration completion acknowledged');
select lives_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),1,'hint')$$,'bounded fixed fallback explanation');
select lives_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),1,'respond')$$,'simulated response never recorded as evidence');
select throws_ok($$insert into public.lesson_events(lesson_id,event_type,source,payload) select id,'maya_whiteboard_applied','maya_mock','{}' from public.lessons$$,'42501',null,'browser cannot forge Maya events');
select throws_ok($$update public.lesson_plans set plan='{}'$$,'42501',null,'browser cannot rewrite plan');
select is((select count(*)::integer from public.ai_runs),0,'raw AI operations hidden');
select is((select count(*)::integer from public.tool_calls),0,'raw tool operations hidden');
select is((select count(*)::integer from public.questions),0,'private answer keys hidden');
reset role;
select is((select count(*)::integer from public.ai_runs),1,'one mock operation telemetry record');
select is((select metadata->>'externalRequests' from public.ai_runs),'0','zero external usage');
select is((select metadata->>'estimatedCostUsd' from public.ai_runs),'0','mock zero cost');
select is((select count(*)::integer from public.tool_calls),1,'validated board tools logged once per application');
select is((select count(*)::integer from public.lesson_events where event_type='maya_whiteboard_applied'),1,'already committed board commands preserved');
select throws_ok($$update public.lesson_plans set plan='{}'$$,'42501',null,'trusted writes cannot rewrite simulation plan');
select throws_ok($$delete from public.lesson_events where source='maya_mock'$$,'42501',null,'mock timeline append-only');
select is((select sum(evidence_count)::integer from public.student_skills where student_id='a6100000-0000-0000-0000-000000000001'),0,'no evidence inferred');
select is((select count(*)::integer from public.learning_evidence),0,'no learning evidence generated');
select is((select count(*)::integer from public.homework_assignments),0,'no homework created');
select is((select count(*)::integer from public.lesson_outcomes),0,'no genuine outcomes');
set local role authenticated;
select lives_ok($$select public.maya_mock_tool_audit((select id from fixture where lesson_position=1),'a6300000-0000-4000-8000-000000000005','get_lesson_context','validated')$$,'approved read tool audited');
select lives_ok($$select public.maya_mock_tool_audit((select id from fixture where lesson_position=1),'a6300000-0000-4000-8000-000000000005','get_lesson_context','validated')$$,'exact tool retry idempotent');
select throws_ok($$select public.maya_mock_tool_audit((select id from fixture where lesson_position=1),'a6300000-0000-4000-8000-000000000005','get_current_objective','validated')$$,'22023',null,'tool retry cannot change scope');
select lives_ok($$select public.maya_mock_tool_audit((select id from fixture where lesson_position=1),gen_random_uuid(),'unapproved','rejected')$$,'rejected tool proposal audited without raw arguments');
select throws_ok($$select public.maya_mock_tool_audit((select id from fixture where lesson_position=1),gen_random_uuid(),'update_mastery','validated')$$,'22023',null,'forbidden tool cannot be audited as valid');
reset role;
select is((select count(*)::integer from public.tool_calls),3,'tool audits deduplicated');
select is((select count(*)::integer from public.lesson_events where event_type='maya_tool_call'),4,'proposed and validated or rejected outcomes durable');
create temp table history_sequence as select event_sequence from public.lessons where schedule_id=(select id from fixture where lesson_position=1);
update public.lessons set event_sequence=2985 where schedule_id=(select id from fixture where lesson_position=1);
set local role authenticated;
select throws_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),1,'hint')$$,'P5003',null,'server history cap enforced');
select throws_ok($$select public.maya_mock_tool_audit((select id from fixture where lesson_position=1),gen_random_uuid(),'get_current_objective','validated')$$,'P5003',null,'tool history cap enforced');
reset role;
update public.lessons set event_sequence=(select event_sequence from history_sequence) where schedule_id=(select id from fixture where lesson_position=1);
select set_config('request.jwt.claims','{"sub":"a6000000-0000-0000-0000-000000000002","session_id":"a6200000-0000-0000-0000-000000000001"}',true);
set local role authenticated;
select throws_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),1,'hint')$$,'42501',null,'cross-family actor denied');
reset role;
select set_config('request.jwt.claims','{"sub":"a6000000-0000-0000-0000-000000000001","session_id":"a6200000-0000-0000-0000-000000000002"}',true);
set local role authenticated;
select public.begin_student_preview('a6100000-0000-0000-0000-000000000001');
select throws_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),1,'hint')$$,'42501',null,'another parent session cannot control teaching');
reset role;
select set_config('request.jwt.claims','{"sub":"a6000000-0000-0000-0000-000000000001","session_id":"a6200000-0000-0000-0000-000000000001"}',true);
update public.lessons set maya_started_at=clock_timestamp()-interval '301 seconds';
set local role authenticated;
select is((public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),1,'hint')->>'reason'),'duration','server-enforced duration expires independently of browser');
select is((select interruption_epoch from public.lessons),2,'expiry cancels pending generation');
select throws_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=1),gen_random_uuid(),2,'advance')$$,'22023',null,'expired teaching cannot resume');
select public.classroom_lifecycle((select id from fixture where lesson_position=1),gen_random_uuid(),'end');
select is((select status from public.lesson_schedules where lesson_position=1 and student_id='a6100000-0000-0000-0000-000000000001'),'scheduled','simulation never changes reservation');
select public.classroom_lifecycle((select id from fixture where lesson_position=2),gen_random_uuid(),'start');
select throws_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=2),gen_random_uuid(),0,'start')$$,'22023',null,'unsupported fraction lesson fails rather than fabricated plan');
select public.classroom_lifecycle((select id from fixture where lesson_position=2),gen_random_uuid(),'end');
select public.classroom_lifecycle((select id from fixture where lesson_position=3),gen_random_uuid(),'start');
select lives_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=3),gen_random_uuid(),0,'start')$$,'inverse-operation planned lesson supported');
select lives_ok($test$do $rate$ begin for n in 1..29 loop perform public.maya_mock_tool_audit((select id from fixture where lesson_position=3),gen_random_uuid(),'get_current_objective','validated'); end loop; end; $rate$;$test$,'bounded tool audit loop setup');
select throws_ok($$select public.maya_mock_tool_audit((select id from fixture where lesson_position=3),gen_random_uuid(),'get_current_objective','validated')$$,'P5002',null,'tool rate limit enforced');
select public.classroom_lifecycle((select id from fixture where lesson_position=3),gen_random_uuid(),'pause');
select lives_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=3),gen_random_uuid(),1,'stop')$$,'explicit stop allowed while lesson paused');
select public.end_student_preview();
select throws_ok($$select public.maya_mock_operation((select id from fixture where lesson_position=3),gen_random_uuid(),2,'hint')$$,'42501',null,'return revokes producer access');
select * from finish();
rollback;
